const n = parseInt(readline());
const keys = readline().split(' ').map(Number);
const about = readline();
let output = '';
for (let char of about) {
  if (char.match(/[0-9]/))
    output += char;
  else if (char.match(/[A-Z]/))
    output += String.fromCharCode(char.charCodeAt() + keys.shift());
}
console.log(output.toLowerCase());
